import{_ as t,o as d,c as o,ax as a}from"./chunks/framework.D0-oyZN4.js";const p=JSON.parse('{"title":"Project Files","description":"Files the Developer Studio CLI creates, reads, and writes — in your project, on your user account, and via environment variables.","frontmatter":{"description":"Files the Developer Studio CLI creates, reads, and writes — in your project, on your user account, and via environment variables."},"headers":[],"relativePath":"cli/reference/project-files.md","filePath":"cli/reference/project-files.md"}'),r={name:"cli/reference/project-files.md"};function i(n,e,s,c,l,h){return d(),o("div",null,[...e[0]||(e[0]=[a('<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /docs/cli/reference/project-files.md for this page in Markdown format</div><h1 id="project-files" tabindex="-1">Project Files <a class="header-anchor" href="#project-files" aria-label="Permalink to &quot;Project Files&quot;">​</a></h1><p>Describes every path <code>gsds</code> touches. Commit rules are stated per file.</p><h2 id="in-your-project" tabindex="-1">In your project <a class="header-anchor" href="#in-your-project" aria-label="Permalink to &quot;In your project&quot;">​</a></h2><h3 id="committed" tabindex="-1">Committed <a class="header-anchor" href="#committed" aria-label="Permalink to &quot;Committed&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Path</th><th>Purpose</th></tr></thead><tbody><tr><td><code>gsds.json</code></td><td>Project-root marker. <code>gsds</code> refuses to run outside a directory containing this file, apart from <code>gsds init</code>. Its <code>cliVersion</code> and <code>templateVersion</code> record which CLI and which template shape the project was scaffolded with; <code>gsds init</code> refreshes <code>cliVersion</code>, which is what clears the stale-version notice. Its <code>dedupe.exclude</code> array names packages or scopes (a trailing <code>/*</code>) that <code>gsds build</code> never externalizes — see <a href="./../share-dependencies.html">Share Dependencies Across Widgets</a></td></tr><tr><td><code>extensions_registry.json</code></td><td>Hand-authored registry of widgets, scripts, and stylesheets in the project. Never regenerated from a folder scan — <code>gsds build</code> validates it and writes only the parts it manages, as described under <a href="./commands.html#gsds-build"><code>gsds build</code></a></td></tr><tr><td><code>connectors_registry.json</code></td><td>Hand-authored registry of Connectors and composite Connectors. Validated and left as written on the same terms</td></tr><tr><td><code>AGENTS.md</code></td><td>AI-agent-oriented project notes seeded by <code>gsds init</code></td></tr><tr><td><code>README.md</code></td><td>Human-oriented project notes seeded by <code>gsds init</code></td></tr><tr><td><code>.gitignore</code></td><td>Adds <code>.gsds/</code> to the ignore list</td></tr></tbody></table><h3 id="not-committed" tabindex="-1">Not committed <a class="header-anchor" href="#not-committed" aria-label="Permalink to &quot;Not committed&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Path</th><th>Purpose</th></tr></thead><tbody><tr><td><code>.gsds/</code></td><td>Connector-test capture output, with sensitive headers redacted. <code>gsds init</code> gitignores this directory</td></tr><tr><td><code>*.lock</code></td><td>Transient. A lock is held next to a registry while a write is in progress, so parallel <code>gsds</code> runs cannot drop each other&#39;s entries. Removed when the write completes</td></tr><tr><td><code>*.tmp</code></td><td>Transient. Staging files written next to their destination and renamed into place, so an interrupted write cannot leave a half-written registry. Removed on every failure path</td></tr></tbody></table><p><code>gsds init</code> adds <code>*.lock</code> and <code>*.tmp</code> to the <code>.gitignore</code> it writes for a new project. A project that already has a <code>.gitignore</code> keeps it exactly as found — <code>gsds init</code> never overwrites or merges into a file it finds, and re-running it changes nothing here — so an older project needs both patterns added by hand.</p><h3 id="ignored-by-gsds-build" tabindex="-1">Ignored by <code>gsds build</code> <a class="header-anchor" href="#ignored-by-gsds-build" aria-label="Permalink to &quot;Ignored by `gsds build`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Path</th><th>Status</th></tr></thead><tbody><tr><td><code>widgets/&lt;name&gt;/widget.json</code></td><td>Never read. Declare the widget in <code>extensions_registry.json</code> instead</td></tr><tr><td><code>widgets/&lt;name&gt;/connectors.json</code></td><td>Never read. Declare Connectors in <code>connectors_registry.json</code> instead</td></tr></tbody></table><p><code>gsds build</code> warns when it finds either file, and when it finds a <code>widgets/&lt;name&gt;/</code> folder with no registry entry at all. Dot-directories and <code>node_modules</code> under <code>widgets/</code> are skipped entirely, so editor caches and installed packages raise no warning. See <a href="./commands.html#gsds-build"><code>gsds build</code></a> for what to do in each case.</p><p>Widget entries live in <code>extensions_registry.json</code>, and must declare a non-empty <code>title</code> and <code>category</code> and exactly one of <code>source</code> or <code>content</code>. Connector permalinks must be unique. Scripts and stylesheets have no separate source manifest either — their entries live only in <code>extensions_registry.json</code> and are edited through <code>gsds script</code> and <code>gsds style</code>.</p><h3 id="written-by-gsds-build" tabindex="-1">Written by <code>gsds build</code> <a class="header-anchor" href="#written-by-gsds-build" aria-label="Permalink to &quot;Written by `gsds build`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Path</th><th>What changes</th></tr></thead><tbody><tr><td><code>widgets/&lt;name&gt;/vite.config.ts</code></td><td>The <code>externalPackages</code> array is patched in place when the widget&#39;s set of shared dependencies changes. Nothing else in the file is touched</td></tr><tr><td><code>widgets/&lt;name&gt;/angular.json</code></td><td><code>architect.build.options.externalDependencies</code> is patched the same way, for Angular widgets</td></tr></tbody></table><p>Both are part of the shared-dependency deduplication mechanism — see <a href="./../share-dependencies.html">Share Dependencies Across Widgets</a>. Commit the result; don&#39;t hand-edit either value.</p><h2 id="in-your-user-account" tabindex="-1">In your user account <a class="header-anchor" href="#in-your-user-account" aria-label="Permalink to &quot;In your user account&quot;">​</a></h2><h3 id="os-keychain" tabindex="-1">OS keychain <a class="header-anchor" href="#os-keychain" aria-label="Permalink to &quot;OS keychain&quot;">​</a></h3><p><code>gsds</code> stores the session token in your operating system&#39;s keychain:</p><table tabindex="0"><thead><tr><th>Platform</th><th>Backend</th></tr></thead><tbody><tr><td>macOS</td><td>Keychain</td></tr><tr><td>Windows</td><td>Credential Store</td></tr><tr><td>Linux</td><td>Secret Service or keyutils via <code>@napi-rs/keyring</code></td></tr></tbody></table><p>Service name: <code>gainsight-developer-studio-cli</code>. One account per profile — <code>default</code> unless you passed <code>--profile &lt;name&gt;</code> to <code>gsds login</code>.</p><h3 id="file-fallback" tabindex="-1">File fallback <a class="header-anchor" href="#file-fallback" aria-label="Permalink to &quot;File fallback&quot;">​</a></h3><p>When the keychain is unavailable — no supported provider, headless CI, or a keychain error — <code>gsds</code> writes to <code>~/.config/gsds/credentials.json</code> (<code>credentials.&lt;profile&gt;.json</code> for a named profile) at file mode <code>0600</code> and prints a one-time warning on stderr.</p><p><code>gsds</code> also checks that mode every time it reads the file, and tightens it back to <code>0600</code> with a one-time warning if it finds the file more permissive — a restored backup or a loose <code>umask</code> cannot leave your token readable without telling you.</p><h3 id="other-files-under-config-gsds" tabindex="-1">Other files under <code>~/.config/gsds/</code> <a class="header-anchor" href="#other-files-under-config-gsds" aria-label="Permalink to &quot;Other files under `~/.config/gsds/`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Path</th><th>Purpose</th></tr></thead><tbody><tr><td><code>current-profile</code></td><td>Tracks which stored profile is current</td></tr><tr><td><code>update-check.json</code></td><td>Cache for the automatic update check: last-checked timestamp, last outcome, and last version installed. Read before deciding whether the 8-hour check window has elapsed</td></tr></tbody></table><h2 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment variables&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Effect</th></tr></thead><tbody><tr><td><code>GSDS_DISABLE_KEYCHAIN=1</code></td><td>Force the file-based credential fallback even when a keychain is available</td></tr><tr><td><code>GSDS_DISABLE_AUTO_UPDATE=1</code></td><td>Skip the automatic update check entirely — no registry call, no install, no cache write</td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li>Session pairing, TTL, and profiles → <a href="./../authenticate.html">Authenticate</a></li><li>Shared dependency deduplication → <a href="./../share-dependencies.html">Share Dependencies Across Widgets</a></li><li>Missing-file error text and recovery → <a href="./troubleshooting.html">Troubleshooting</a></li><li>Command flags → <a href="./commands.html">Command reference</a></li></ul>',30)])])}const g=t(r,[["render",i]]);export{p as __pageData,g as default};
